import{_ as o,c as a,o as t,a3 as n}from"./chunks/framework.BNw1pucY.js";const g=JSON.parse('{"title":"Changelog","description":"Changelog for @grok/agent-sdk releases.","frontmatter":{"title":"Changelog","description":"Changelog for @grok/agent-sdk releases."},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),s={name:"changelog.md"};function i(r,e,d,c,l,h){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="_0-7-3-2026-11-24" tabindex="-1">0.7.3 (2026-11-24) <a class="header-anchor" href="#_0-7-3-2026-11-24" aria-label="Permalink to &quot;0.7.3 (2026-11-24)&quot;">​</a></h2><h3 id="behavior-changes" tabindex="-1">Behavior changes <a class="header-anchor" href="#behavior-changes" aria-label="Permalink to &quot;Behavior changes&quot;">​</a></h3><ul><li>Unfiltered <code>reminders.list()</code> calls and <code>GET /v1/dev/reminders</code> return only live reminders; lists filtered by <code>purpose</code> or <code>continuationToken</code> keep finished reminders.</li><li>Runtime and CLI log tags use the <code>sdk</code> prefix (<code>[sdk]</code>, <code>[sdk:otel]</code>, <code>[sdk/slack]</code>) instead of <code>bdk</code>.</li></ul><h3 id="new" tabindex="-1">New <a class="header-anchor" href="#new" aria-label="Permalink to &quot;New&quot;">​</a></h3><ul><li>Bitbucket Cloud and Data Center support landed (breaking change: Bitbucket and GitLab clients and handles now require <code>transport</code>).</li><li><code>AGENT_SDK_OTEL_SEMCONV</code> adds OpenTelemetry GenAI semantic convention trace formats, with opt-in message capture via <code>OTEL_INSTRUMENTATION_GENAI_CAPTURE_MESSAGE_CONTENT</code> (see <a href="./guides/opentelemetry.html#trace-format">OpenTelemetry</a>).</li><li>Direct HTTP MCP servers support URL-mode elicitation in Slack and the playground, showing a private sign-in link and retrying after sign-in.</li><li><code>SlackMessage.actionToken</code> exposes Slack&#39;s <code>action_token</code> on inbound <code>app_mention</code> and <code>message</code> events.</li></ul><h3 id="fixes" tabindex="-1">Fixes <a class="header-anchor" href="#fixes" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li>On Cursor hosting, scoped-package agents (<code>@scope/name</code>) store session records, events, continuations, and logs in framework file storage so history and event views populate.</li><li>In the playground, the run-history table includes all of its compiled styles.</li></ul><h2 id="_0-7-2-2026-11-20" tabindex="-1">0.7.2 (2026-11-20) <a class="header-anchor" href="#_0-7-2-2026-11-20" aria-label="Permalink to &quot;0.7.2 (2026-11-20)&quot;">​</a></h2><h3 id="behavior-changes-1" tabindex="-1">Behavior changes <a class="header-anchor" href="#behavior-changes-1" aria-label="Permalink to &quot;Behavior changes&quot;">​</a></h3><ul><li><code>cursorAccount</code> channel configurations now accept up to 50 repositories or projects (up from 20) across GitHub, Origin, GitLab, and Bitbucket, and reject GitHub and Origin repository names longer than 140 characters.</li><li><code>channels</code> is now a reserved agent slug (alongside <code>v1</code>, <code>playground</code>, and <code>docs</code>) so multi-agent slugs do not collide with hosted channel routes.</li></ul><h3 id="new-1" tabindex="-1">New <a class="header-anchor" href="#new-1" aria-label="Permalink to &quot;New&quot;">​</a></h3><ul><li>The <a href="./guides/per-user-connections.html">Per-user MCP connections</a> guide explains how to run hosted <code>cursorAccount</code> MCP connectors as the signed-in user. It covers <code>credentials: &quot;individual&quot;</code> declarations, user sign-in, and turns without a signed-in user.</li></ul><h3 id="fixes-1" tabindex="-1">Fixes <a class="header-anchor" href="#fixes-1" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li><code>agent-sdk channels teams doctor</code> now accepts the public hosted Teams endpoint URL (<code>https://api.cursor.com/v1/agent-sdk/&lt;applicationId&gt;/channels/&lt;channelId&gt;</code>, and <code>/&lt;slug&gt;/channels/&lt;channelId&gt;</code> for multi-agent deployments) alongside the legacy <code>/engine</code> path.</li><li>When a direct tool call on an individual <code>cursorAccount</code> MCP connection fails because the user has not connected that server, the runtime shows the Connect prompt in the playground and Slack instead of returning only an authentication error.</li><li>In the playground, a tooltip opened by hover or focus now closes when the part of the screen it is on is hidden.</li></ul><h2 id="_0-7-1-2026-11-20" tabindex="-1">0.7.1 (2026-11-20) <a class="header-anchor" href="#_0-7-1-2026-11-20" aria-label="Permalink to &quot;0.7.1 (2026-11-20)&quot;">​</a></h2><h3 id="fixes-2" tabindex="-1">Fixes <a class="header-anchor" href="#fixes-2" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li>On Cursor hosting, scheduled runs record trace events under the platform session id so they appear in the Trace tab. Before, scheduled runs wrote traces under a local id and the Trace tab stayed empty.</li><li>GitHub and Origin <code>cursorAccount</code> connections ignore GitLab and Bitbucket repository entries in the shared event list instead of failing startup.</li><li><code>cursorAccount</code> MCP server name matching trims surrounding whitespace on server names and identifiers and rejects blank names.</li></ul><h2 id="_0-7-0-2026-11-19" tabindex="-1">0.7.0 (2026-11-19) <a class="header-anchor" href="#_0-7-0-2026-11-19" aria-label="Permalink to &quot;0.7.0 (2026-11-19)&quot;">​</a></h2><h3 id="minimum-versions" tabindex="-1">Minimum versions <a class="header-anchor" href="#minimum-versions" aria-label="Permalink to &quot;Minimum versions&quot;">​</a></h3><ul><li><code>@grok/agent-sdk</code> requires <code>@cursor/sdk</code> 1.4.2, so each model call&#39;s usage arrives as a <code>model_call.completed</code> event.</li></ul><h3 id="behavior-changes-2" tabindex="-1">Behavior changes <a class="header-anchor" href="#behavior-changes-2" aria-label="Permalink to &quot;Behavior changes&quot;">​</a></h3><ul><li>The <code>[cloud agent stopped]</code> wake message now holds only the agent id and its status, and tells the model to call <code>cloud__get</code> to read the agent&#39;s <code>result</code>. It no longer holds the agent&#39;s details.</li><li>On Cursor hosting, a cloud agent that a <code>cursor-cloud-agents</code> conversation launched wakes that conversation once when its run stops. This includes a run that someone else cancelled. Nothing polls the agent. If no wake comes, ask the bot to check the agent. A stop in the middle of a turn does not wake the conversation yet.</li><li>Launches off Cursor hosting, from a mount that sets its own <code>apiKey</code>, or with <code>envVars</code> are not watched, and return <code>watching: false</code>. A launch that Cursor hosting cannot watch also returns <code>watching: false</code>. Before, the stop watch polled the agent every minute.</li><li>A wake that reached no session, such as a failed session restore or a busy session, is sent again every minute, up to 10 times.</li><li>With a <code>skills</code> callback, the skills index lists only the discovered skills available in the mounted tree, rechecked each turn. Skills whose availability check fails are left out.</li></ul><h3 id="new-2" tabindex="-1">New <a class="header-anchor" href="#new-2" aria-label="Permalink to &quot;New&quot;">​</a></h3><ul><li><code>teamsChannel()</code> from <code>@grok/agent-sdk/channels/teams</code> connects an Azure Bot that you own to Microsoft Teams personal chats, group chats, and channel posts. It runs under <code>agent-sdk dev</code> and <code>agent-sdk serve</code>. The <code>agent-sdk channels teams</code> commands store the bot&#39;s credentials, build the Teams app package, and check the setup.</li><li><code>teamsChannel()</code> reacts with 👀 (<code>1f440_eyes</code>) to each accepted inbound message when its turn starts. Set <code>reply.ack</code> to another Teams reaction id to change the reaction, or to <code>false</code> to turn it off for the channel. Return <code>quiet: true</code> from an <code>onAppMention</code>, <code>onDirectMessage</code>, or <code>onChannelPost</code> handler to start that message&#39;s turn without the reaction.</li><li><code>ctx.steer(message, { deliveryId })</code> on channel event and hook contexts (<code>SessionContext</code>) and on tool contexts (<code>ToolContext</code>) adds a message to the agent&#39;s own running turn through <code>Run.steer</code>. It never starts a turn, opens a session, or queues the message: it resolves to <code>steered</code>, <code>no_turn</code>, or <code>not_delivered</code>.</li><li><code>getCloudAgent</code> from <code>@grok/agent-sdk/extensions/cursor-cloud-agents</code> and the <code>cloud__get</code> tool return <code>result</code>, the final answer of the agent&#39;s latest run, once the agent has stopped and that run finished. An errored or expired run has no <code>result</code>. Use it to read a cloud agent&#39;s report or JSON from your own code. For a stopped agent, they also read the latest run from the Cloud Agents API, and fail if that read fails.</li><li><code>ReminderHostApi.fireNow(id)</code> fires an armed reminder as soon as the platform can, through its normal claim.</li><li><code>Extension.namespace</code> is the namespace an agent mounted the extension under, for a tree that names its own <code>&lt;ns&gt;__&lt;name&gt;</code> contributions.</li><li><code>ReminderHostApi.createRequest(input)</code> returns the request that <code>create</code> would send, validated the same way, without creating the reminder.</li><li><code>launchCloudAgent</code> takes an optional <code>agentId</code>. Pass the same id again to retry a launch that timed out or failed: when the first launch created the agent, you get that agent and no second agent starts. A launch with <code>cloud.envVars</code> cannot take an <code>agentId</code>.</li></ul><h3 id="fixes-3" tabindex="-1">Fixes <a class="header-anchor" href="#fixes-3" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li>On Cursor hosting, a retried delivery continues on the cloud agent that its first attempt created, even when that attempt stopped before it recorded the agent. Before, the retry launched a second cloud agent that did the same work. A retry of a cancelled cloud run stays cancelled. An agent that sets <code>cloud.envVars</code> can still start a second cloud agent on a retry.</li><li>On Cursor hosting, <code>host.reminders.dispatch()</code> runs the reminder&#39;s handler once. Before, it failed with HTTP 405, and the handler ran again at the reminder&#39;s fire time.</li><li>The CLI writes stored credentials, MCP OAuth tokens, and <code>.env.local</code> so that only your user can read them. It narrows files that earlier versions wrote the next time it reads them.</li><li>In Slack, images in a reply that arrives while a turn runs reach the follow-up turn. Before, only the reply&#39;s text did.</li><li>In Slack, a file that the agent can&#39;t attach is named in the prompt with the reason, instead of dropped without a word. Files shared from another workspace now download, and a video sends its poster frame as an image.</li><li>In Slack, channel, user, and user group mentions that arrive without a label reach the model as names. Before, an unlabeled channel mention read as <code>#channel</code>. Private channels and DMs show their id.</li><li>On an HTTP 403, <code>agent-sdk deploy</code> prints the server&#39;s reason instead of guessing a cause.</li></ul><h2 id="_0-6-0-2026-11-03" tabindex="-1">0.6.0 (2026-11-03) <a class="header-anchor" href="#_0-6-0-2026-11-03" aria-label="Permalink to &quot;0.6.0 (2026-11-03)&quot;">​</a></h2><h3 id="minimum-versions-1" tabindex="-1">Minimum versions <a class="header-anchor" href="#minimum-versions-1" aria-label="Permalink to &quot;Minimum versions&quot;">​</a></h3><ul><li><code>@grok/agent-sdk</code> requires <code>@cursor/sdk</code> 1.3.0.</li></ul><h3 id="behavior-changes-3" tabindex="-1">Behavior changes <a class="header-anchor" href="#behavior-changes-3" aria-label="Permalink to &quot;Behavior changes&quot;">​</a></h3><ul><li>On Cursor-managed hosting, when the team turns on its Cloud Agent Allowlist, a turn checks the <code>url:</code> and <code>command:</code> connections it opens against that list. It also checks their network hosts against the team&#39;s network allowlist for Cloud Agents. Before, it used the team&#39;s MCP Allowlist. Agents that you run with <code>agent-sdk serve</code> keep the MCP Allowlist.</li><li>On Cursor-managed hosting, when the team turns on its Cloud Agent Allowlist, the Cursor backend checks each <code>cursorAccount</code> connection against that list. The turn&#39;s local MCP checks no longer refuse these connections.</li><li>An agent with <code>cursorAccount</code> connections starts its shared workspace after those connections resolve. Other agents still start it when the server starts.</li></ul><h2 id="_0-5-0-2026-10-28" tabindex="-1">0.5.0 (2026-10-28) <a class="header-anchor" href="#_0-5-0-2026-10-28" aria-label="Permalink to &quot;0.5.0 (2026-10-28)&quot;">​</a></h2><h3 id="breaking-changes" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h3><ul><li>No change to which file tools an <code>fs</code> agent has or what they do. Their results now use Cursor&#39;s native tool-call shape instead of Agent SDK&#39;s earlier MCP-style text, in <code>tool_call</code> events, transcripts, and direct tool calls. The same holds without <code>fs</code>. Update code that parses these results. For example, a direct <code>read</code> call returns <code>{ status: &quot;success&quot;, value: { content } }</code> instead of numbered lines.</li><li>With <code>fs</code>, a <code>tools</code> list gets only the file tools it names. Add <code>&quot;read&quot;</code>, <code>&quot;ls&quot;</code>, <code>&quot;glob&quot;</code>, <code>&quot;grep&quot;</code>, <code>&quot;edit&quot;</code>, and <code>&quot;delete&quot;</code> to keep them.</li><li><code>@grok/agent-sdk/executors</code> is removed. Remove that import. The npm package has no replacement.</li><li><code>synthesizeFileSystemTools</code> is removed. Pass your tree as <code>fs</code>.</li><li><code>nearestNeighborMissHint</code> is removed. Read suggests nearby names when a file is missing.</li><li><code>RunnerTurnRequest</code> carries <code>fs</code>, <code>reportedWorkspacePath</code>, and <code>settingSources</code> instead of <code>root</code> and <code>subagentInherit</code>.</li></ul><h3 id="minimum-versions-2" tabindex="-1">Minimum versions <a class="header-anchor" href="#minimum-versions-2" aria-label="Permalink to &quot;Minimum versions&quot;">​</a></h3><ul><li><code>@grok/agent-sdk</code> requires <code>@cursor/sdk</code> 1.2.0.</li></ul><h3 id="behavior-changes-4" tabindex="-1">Behavior changes <a class="header-anchor" href="#behavior-changes-4" aria-label="Permalink to &quot;Behavior changes&quot;">​</a></h3><ul><li>With <code>fs</code>, <code>AGENTS.md</code> and <code>.cursor/rules/</code> in the workspace load as project rules, as they do on the host. Don&#39;t make a checkout you don&#39;t trust the workspace.</li><li>With <code>fs</code>, omitting <code>tools</code> gives every tool the tree can back, including subagents, web search, web fetch, todos, and MCP.</li><li>With <code>fs</code>, a <code>tools</code> list that names a tool the tree can&#39;t run, such as <code>readLints</code>, leaves it out with a warning. Before, <code>readLints</code> with <code>fs</code> failed validation.</li><li>With <code>fs</code>, LS, Grep, and Glob search the workspace when a call names no path.</li><li>With <code>fs</code>, each turn gets an empty <code>/tmp</code>. Large web results are written there.</li><li>With <code>fs</code>, subagents work on the agent&#39;s tree, and their writes land in it as the agent&#39;s own do. Before, each subagent wrote to its own copy.</li><li><code>local.sandbox</code> works with <code>fs</code>. A tool call that needs approval, such as an external MCP call, fails closed. File access doesn&#39;t change.</li><li>With <code>local.sandbox</code> and no <code>fs</code>, an agent with shell in <code>tools</code>, or with <code>tools</code> omitted, can read outside the session workspace with the file tools, as its shell already could. Writes and deletes outside it are still refused.</li><li>With <code>local.sandbox</code> and no <code>fs</code>, an agent whose <code>tools</code> list file tools and no shell runs on its session workspace, mounted at <code>/workspace</code>, and its reads stay inside it. Cursor hooks don&#39;t run for it, so a Slack follow-up waits for the turn to end. <code>.cursor/mcp.json</code> from its working directory isn&#39;t loaded, host git status doesn&#39;t reach the model, and its skills are at <code>/agent/skills</code>.</li><li>An agent tool can be named <code>Read</code>, <code>Grep</code>, or another file tool&#39;s name.</li></ul><h3 id="new-3" tabindex="-1">New <a class="header-anchor" href="#new-3" aria-label="Permalink to &quot;New&quot;">​</a></h3><ul><li><code>workspace</code> sets the folder inside <code>fs</code> that the agent works in. For a sandboxed agent without shell, it sets where the session workspace is mounted.</li></ul><h3 id="fixes-4" tabindex="-1">Fixes <a class="header-anchor" href="#fixes-4" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li>An agent that exports OpenTelemetry traces no longer logs a duplicate propagator registration error on its first HTTP request.</li></ul><h2 id="_0-4-0-2026-10-27" tabindex="-1">0.4.0 (2026-10-27) <a class="header-anchor" href="#_0-4-0-2026-10-27" aria-label="Permalink to &quot;0.4.0 (2026-10-27)&quot;">​</a></h2><h3 id="breaking-changes-1" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes-1" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h3><ul><li>The <code>FileSystem</code> type, its helpers, and its errors match the file tools, and the package root exports <code>readOnlyFs</code>.</li></ul><h3 id="fixes-5" tabindex="-1">Fixes <a class="header-anchor" href="#fixes-5" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li>A reply in a Slack thread that a schedule started continues that session.</li><li>A hosted Slack agent with <code>botMentions.allowFrom</code> starts a session when an allowed bot mentions it.</li></ul><h2 id="_0-3-0-2026-10-25" tabindex="-1">0.3.0 (2026-10-25) <a class="header-anchor" href="#_0-3-0-2026-10-25" aria-label="Permalink to &quot;0.3.0 (2026-10-25)&quot;">​</a></h2><ul><li>GA Release</li><li><code>persistent</code> option is removed from <code>defineAgent</code></li></ul><h2 id="_0-2-29-2026-10-23" tabindex="-1">0.2.29 (2026-10-23) <a class="header-anchor" href="#_0-2-29-2026-10-23" aria-label="Permalink to &quot;0.2.29 (2026-10-23)&quot;">​</a></h2><ul><li>Bug Fixes</li></ul>',52)])])}const m=o(s,[["render",i]]);export{g as __pageData,m as default};
